  font-weight: 800;
}

.leader__badge {
  display: inline-block;
  margin-left: 0.4em;
  border-radius: 1000px;
  padding: 0.15em 0.6em;
  background: var(--c-pink);
  color: var(--c-white);
  font-size: 0.55em;
  vertical-align: middle;
}
.leader.is-winner .leader__name::after { content: none; }

/* ---------- Quizzy app additions (moderator area) ---------- */

.admin-main { width: 100%; }

.breadcrumbs a { text-decoration: none; }

.quiz-list { list-style: none; padding: 0; margin: 0; }
.quiz-tile { margin-bottom: 0; padding: 24px; }
.quiz-tile__link { display: block; text-decoration: none; }
.quiz-tile__link:hover { color: var(--c-blue); }
.quiz-tile h3 { margin-bottom: 8px; }

