.question-item { margin-bottom: 16px; }
.question-item__content { min-width: 0; }
.question-item__options li { white-space: normal; }

.option-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px 20px;
  align-items: end;
}
.option-row__text { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.option-row__text .input { width: 100%; }
.option-row__correct { align-self: end; margin-bottom: 14px; }

.play-options { list-style: none; padding: 0; margin: 0; }
.play-options li { list-style: none; }
.play-options form { margin: 0; }
.play-option { width: 100%; }

.preview-banner { border-radius: 0; margin-bottom: 24px; }

.export-json {
  margin: 0;
  padding: 20px;
  border-radius: 16px;
  background: #10152a;
  color: #eef1ff;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 14px;
  line-height: 1.55;
  overflow-x: auto;
  white-space: pre;
}

/* ---------- Live game additions ---------- */

.screen-controls__join { font-weight: 600; }
.screen-controls__url {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(16px, 1.4vw, 24px);
  overflow-wrap: anywhere;
}

.play-options li { display: flex; flex-direction: column; }
.play-choice-mark { margin-top: 6px; text-align: center; font-size: 14px; font-weight: 700; color: var(--c-pink); }
